// ==UserScript==
// @name        Combined Spark Calculator
// @namespace   Violentmonkey Scripts
// @icon        data:image/png;base64,
// @version     1.1.0
//
// @match       https://chronogenesis.net/*
// @grant       none
//
// @author      Matthew "M-AS" Nguyen
// @description Calculates chances of multiple sparks proccing
// ==/UserScript==

(function() {
	'use strict';

	// Your code here!

	// https://www.geeksforgeeks.org/javascript/find-all-the-combinations-of-the-array-values-in-javascript/
	function combination(arr) {
		const res = [];

		function help(curr, remain) {
			if (remain.length === 0) {
				if (curr.length > 0) {
					res.push(curr);
				}
				return;
			}

			help([...curr, remain[0]], remain.slice(1));

			help(curr, remain.slice(1));
		}

		help([], arr);
		return res;
	}



	const umas = document.getElementsByClassName("friend-card-main"); // a list of matching elements, *not* the element itself
	// console.log(umas);

	function makeCheckboxes() {
		for (const uma of umas) {
			const cfd = uma.getElementsByClassName("friend-card-fd-cfd")[0];

			const factors = cfd.getElementsByClassName("factor-body-base"); // a list of matching elements, *not* the element itself

			for (const factor of factors) {
				const name = factor.firstElementChild.firstChild.textContent.trim();

				if (!document.getElementById(name)) {
					const checkbox = document.createElement('input');
					checkbox.type = "checkbox";
					checkbox.name = "spark";
					checkbox.value = name;
					checkbox.id = name;
					checkbox.style.marginRight = "8px";
					factor.appendChild(checkbox);
				}


			}

		}

	}


	function calculateSparks() {
		const sparks = [];
		// sparks.push("Medium", "Uma Stan", "Let's Pump Some Iron!", "Tenno Sho (Spring)");

		var checkedBoxes = document.querySelectorAll('input[name=spark]:checked');
		for (const checkbox of checkedBoxes) {
			if (!sparks.includes(checkbox.value)) {
				sparks.push(checkbox.value);
			}
		}

		if (sparks.length < 1) {
			return;
		}

		var nodesToRemove = document.querySelectorAll('div.results');
		for (const toRemove of nodesToRemove) {
			toRemove.remove();
		}


		for (const uma of umas) {
			console.log(uma);

			const newCfd = document.createElement("div");
			newCfd.className = "results";
			newCfd.style.paddingTop = "0px";
			newCfd.style.paddingBottom = "40px";
			newCfd.style.paddingLeft = "24px";
			newCfd.style.fontSize = "0.9em";

			uma.appendChild(newCfd);



			// console.log(result);

			const newRows = [];


			const _sparks = [];
			for (const spark of sparks) {
				const xpath = `.//div[normalize-space(text())="${spark}"]`;

				const factor = document.evaluate(
					xpath,
					uma,
					null,
					XPathResult.FIRST_ORDERED_NODE_TYPE,
					null
				).singleNodeValue;

				// console.log(xpath, factor);

				if (factor != null) {
					_sparks.push(spark);
				}

			}

			for (let i = 0; i < _sparks.length; i++) {
				const newRow = document.createElement("div");
				newRow.className = "friend-card-fd-fd-child";
				// newRow.style.borderTop = "1px solid grey";
				// newRow.style.padding = "8px";
				// newRow.style.backgroundColor = "#321";
				// // newRow.style.borderTop = "1px solid black";
				// newRow.style.margin = `8px ${i * 12}px`;
				// newRow.style.borderRadius = "12px";
				// // newRow.style.display = "inline-block";
				// newRow.style.padding = "8px";
				newRows.push(newRow);
				newCfd.appendChild(newRow);
			}
			const combos = combination(_sparks);
			for (const combo of combos) {

				var result = 1.00;

				const newFactor = document.createElement("div");
				const newFactorText = document.createElement("div");
				newFactorText.style.color = "#ffcf33";
				const newFactorRate = document.createElement("div");

				for (let i = 0; i < combo.length; i++) {
					// const xpath = `.//div[text()='${spark} ']`;
					const spark = combo[i];
					const xpath = `.//div[normalize-space(text())="${spark}"]`;
					// const xpath = `.//div[contains(., '${spark}')]`;


					// console.log(xpath);
					const factors = document.evaluate(
						xpath,
						uma,
						null,
						XPathResult.UNORDERED_NODE_SNAPSHOT_TYPE,
						null
					);

					// console.log(xpath, factors);

					if (factors.snapshotLength == 0) {
						result = 0.00;
						break;
					}
					var chanceToFail = 1.0;
					for (let j = 0; j < factors.snapshotLength; j++) {
						var factor = factors.snapshotItem(j);
						const percent = factor.nextElementSibling.textContent;
						chanceToFail *= 1 - (Number(percent.substring(0, percent.length - 1)) / 100);
					}

					result *= 1 - chanceToFail;


					const newSubfactor = document.createElement("span");
					const newSubfactorText = document.createTextNode(spark);
					newSubfactor.style.color = getComputedStyle(factor).color;
					newSubfactor.appendChild(newSubfactorText);

					newFactorText.appendChild(newSubfactor);
					if (i < combo.length - 1) {
						newFactorText.appendChild(document.createTextNode(" × "));
					}
				}

				// const newFactorTextText = document.createTextNode(combo.join(" × "));
				const newFactorRateText = document.createTextNode((result * 100).toFixed(2) + "%");
				// newFactor.className = "factor-body-base common-hi";
				// newFactor.className = "factor-body-base common";
				newFactor.className = "factor-body-base common";

				// newFactor.style.borderColor =

				newFactorText.className = "factor-text";
				newFactorRate.className = "factor-rate";


				// newFactorText.appendChild(newFactorTextText);
				newFactorRate.appendChild(newFactorRateText);
				newFactor.appendChild(newFactorText);
				newFactor.appendChild(newFactorRate);
				newRows[_sparks.length - combo.length].appendChild(newFactor);
				// const borderColor = getComputedStyle(newFactor).borderColor;
				// console.log(borderColor);

				// newFactor.style.borderColor = borderColor.slice(0, -1) + "," + result + ")";
				// newFactor.style.borderColor = "white";
				// newFactor.style.borderWidth = `${combo.length}px`;
				newFactor.style.borderColor = `color-mix(in hsl, #ffcf33 ${(combo.length - 1) / (sparks.length - 1) * 100}%, #ffffff25)`;
				// console.log(newFactor.style.borderColor);
			}
		}
		return;

	}

	const buttonPanel = document.createElement('div');
	buttonPanel.style.position = "fixed";
	buttonPanel.style.right = "10px";
	buttonPanel.style.bottom = "10px";
	buttonPanel.style.zIndex = "999";



	const sparksButton = document.createElement('button');
	const sparksButtonLabel = document.createTextNode('Calculate Sparks');
	sparksButton.addEventListener('click', calculateSparks);
	sparksButton.appendChild(sparksButtonLabel);

	const checkboxerButton = document.createElement('button');
	const checkboxerButtonLabel = document.createTextNode('Refresh Checkboxes');
	checkboxerButton.addEventListener('click', makeCheckboxes);
	checkboxerButton.appendChild(checkboxerButtonLabel);

	buttonPanel.appendChild(checkboxerButton);
	buttonPanel.appendChild(sparksButton);
	document.body.appendChild(buttonPanel);


})();
